"use client";
import{useEffect,useState}from'react';import{Button}from'../ui/Button';import{Card}from'../ui/Card';import{trackEvent}from'../../lib/analytics/client';
interface Usage{limit:number;used:number;remaining:number}type Product='single_credit'|'bundle_10'|'bundle_25'|'bundle_100';type RW=Window&{Razorpay?:new(o:Record<string,unknown>)=>{open:()=>void}};const products:{id:Product;label:string;price:number}[]=[{id:'single_credit',label:'1 credit',price:5},{id:'bundle_10',label:'10 credits',price:39},{id:'bundle_25',label:'25 credits',price:79},{id:'bundle_100',label:'100 credits',price:199}];
export function DashboardExperience(){const[usage,setUsage]=useState<Usage>({limit:2,used:0,remaining:2}),[credits,setCredits]=useState(0),[history,setHistory]=useState<any[]>([]),[loading,setLoading]=useState(true),[busy,setBusy]=useState('');async function refresh(){setLoading(true);try{const[u,c,h]=await Promise.all([fetch('/api/usage'),fetch('/api/credits'),fetch('/api/history')]);if(u.ok)setUsage(await u.json());if(c.ok)setCredits((await c.json()).credits||0);if(h.ok)setHistory((await h.json()).items||[])}finally{setLoading(false)}}useEffect(()=>{void refresh()},[]);async function buy(product:Product){trackEvent('checkout_started',{product});setBusy(product);try{const r=await fetch('/api/payment/create-order',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({product})}),d=await r.json();if(!r.ok){setBusy('error');return}const script=document.createElement('script');script.src='https://checkout.razorpay.com/v1/checkout.js';script.async=true;script.onload=()=>{const R=(window as RW).Razorpay;if(!R){setBusy('error');return}new R({key:d.keyId,amount:d.amount,currency:d.currency,name:'NoMeta',description:d.label,order_id:d.orderId,handler:async(payment:{razorpay_order_id:string;razorpay_payment_id:string;razorpay_signature:string})=>{const v=await fetch('/api/payment/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payment)});if(v.ok){trackEvent('payment_verified',{product});await refresh();setBusy('')}else{trackEvent('payment_failed',{product});setBusy('error')}},modal:{ondismiss:()=>setBusy('')}}).open()};script.onerror=()=>setBusy('error');document.body.appendChild(script)}catch{setBusy('error')}}return <div className="nm-dashboard"><div className="nm-dashboard__grid"><Card className="nm-dashboard-card nm-dashboard-card--primary"><span className="nm-eyebrow">Today</span><div className="nm-dashboard-stat">{loading?'—':usage.remaining}</div><h3>free cleanings remaining</h3><p>{usage.used} of {usage.limit} successful free cleanings used today.</p><Button href="/clean" style={{marginTop:18}}>Clean a photo</Button></Card><Card className="nm-dashboard-card"><span className="nm-eyebrow">Paid credits</span><div className="nm-dashboard-stat">{loading?'—':credits}</div><h3>available credits</h3><p>Credits never expire.</p><div style={{display:'grid',gap:8,marginTop:18}}>{products.map(p=><Button key={p.id} onClick={()=>buy(p.id)} variant="secondary" disabled={!!busy}>{busy===p.id?'Preparing…':`${p.label} · ₹${p.price}`}</Button>)}</div>{busy==='error'&&<p className="nm-dashboard-message nm-dashboard-message--error">Checkout could not be completed. No credit was added.</p>}</Card><Card className="nm-dashboard-card"><span className="nm-eyebrow">Privacy</span><div className="nm-dashboard-stat nm-dashboard-stat--word">Local-first</div><h3>your originals stay in your browser</h3><p>No original images or raw metadata payloads are stored.</p><Button href="/privacy" variant="ghost" style={{marginTop:18}}>Read privacy details</Button></Card></div><Card className="nm-dashboard-history"><div className="nm-dashboard-history__head"><div><span className="nm-eyebrow">Activity</span><h2>Cleaning history</h2></div><span className="nm-badge nm-badge--neutral"><i className="nm-badge__dot"/>No originals stored</span></div>{history.length?<div style={{display:'grid',gap:8,marginTop:20}}>{history.map(item=><div key={item.id} style={{display:'flex',justifyContent:'space-between',gap:12,padding:'12px 0',borderBottom:'1px solid var(--line)'}}><span>{new Date(item.created_at).toLocaleString()} · {(item.format||'image').toUpperCase()}</span><span>{item.entitlement==='free'?'Free':'Credit'} · {item.mode}</span></div>)}</div>:<div className="nm-dashboard-empty"><strong>Nothing to show yet</strong><span>Successful cleaning events will appear here without storing photos or metadata payloads.</span></div>}</Card></div>}
